def semver_sort(versions):
    def parse(v):
        # strip build metadata
        main_and_pre = v.split('+', 1)[0]
        if '-' in main_and_pre:
            main, pre = main_and_pre.split('-', 1)
        else:
            main, pre = main_and_pre, None
        major, minor, patch = (int(x) for x in main.split('.'))
        if pre is not None:
            ids = pre.split('.')
            pre_key = []
            for ident in ids:
                if ident.isdigit():
                    pre_key.append((0, int(ident), ''))
                else:
                    pre_key.append((1, 0, ident))
            has_pre = 0
        else:
            pre_key = []
            has_pre = 1
        return (major, minor, patch, has_pre, pre_key)

    return sorted(versions, key=parse)

